<?php
/**
 * Letters of recommendation (table recommendation_letters, migration 072).
 *
 *  - Only for an enrolment whose certificate has been generated (not withdrawn).
 *  - Generated by an admin/superadmin or by the student's assigned tutor; emailed to the student and listed
 *    on their Certificates page.
 *  - The body is written by the system from the student's course (lor_default_body()); only admins and
 *    superadmins can edit it.
 *  - The PDF shows the institute logo and name, the title, the student's registration number, the date it was
 *    generated, and a faint logo watermark. Verified at verify/?reg=<registration no>.
 */
require_once __DIR__ . '/CertificateService.php';

if (!function_exists('lor_get_by_reg')) {
    /** The letter joined with what the PDF and pages need, or null. */
    function lor_get_by_reg(PDO $db, int $registrationId): ?array
    {
        return lor_fetch($db, 'l.registration_id = ?', $registrationId);
    }

    function lor_get(PDO $db, int $id): ?array
    {
        return lor_fetch($db, 'l.id = ?', $id);
    }

    function lor_get_by_hash(PDO $db, string $hash): ?array
    {
        return preg_match('/^[a-f0-9]{32}$/', $hash) ? lor_fetch($db, 'l.verify_hash = ?', $hash) : null;
    }

    function lor_fetch(PDO $db, string $where, $arg): ?array
    {
        try {
            $st = $db->prepare(
                "SELECT l.*, r.full_name, r.registration_no, r.email AS reg_email, r.user_id, u.email AS login_email,
                        c.certificate_no, c.status AS certificate_status, c.tutor_id, c.tutor_name, c.snapshot_course
                 FROM recommendation_letters l
                 JOIN registrations r ON r.id = l.registration_id
                 LEFT JOIN users u ON u.id = r.user_id
                 JOIN certificates c ON c.id = l.certificate_id
                 WHERE $where LIMIT 1"
            );
            $st->execute([$arg]);
            return $st->fetch(PDO::FETCH_ASSOC) ?: null;
        } catch (PDOException $e) {
            return null;   // table not installed yet (migration 072)
        }
    }

    /** The certificate a letter can be based on, or null when none has been generated. */
    function lor_certificate(PDO $db, int $registrationId): ?array
    {
        $st = $db->prepare("SELECT * FROM certificates WHERE registration_id = ? AND status <> 'withdrawn' ORDER BY id DESC LIMIT 1");
        $st->execute([$registrationId]);
        return $st->fetch(PDO::FETCH_ASSOC) ?: null;
    }

    /** True when $tutorUserId is a tutor assigned to the student of this enrolment. */
    function lor_tutor_can(PDO $db, int $tutorUserId, int $registrationId): bool
    {
        $st = $db->prepare(
            "SELECT 1 FROM registrations r
             JOIN tutor_students ts ON ts.user_id = r.user_id
             JOIN tutors t ON t.id = ts.tutor_id
             WHERE r.id = ? AND t.user_id = ? LIMIT 1"
        );
        $st->execute([$registrationId, $tutorUserId]);
        return (bool) $st->fetchColumn();
    }

    /** Topics the course covers, from its description (one topic per line), else its overview sentence. */
    function lor_course_topics(array $course): array
    {
        $lines = array_values(array_filter(array_map(
            fn($l) => rtrim(trim(preg_replace('/\s+/', ' ', $l)), " .;,]"),
            preg_split('/\r\n|\r|\n/', (string) ($course['description'] ?? ''))
        ), fn($l) => $l !== '' && mb_strlen($l) <= 90));
        return count($lines) >= 2 ? array_slice($lines, 0, 6) : [];
    }

    /** The letter text the system writes from the student's course and certificate. Plain text, paragraphs split by blank lines. */
    function lor_default_body(PDO $db, int $registrationId): string
    {
        $st = $db->prepare(
            "SELECT r.full_name, r.registration_no, r.created_at, r.studies_completed_at, r.study_mode,
                    c.title, c.description, c.overview, c.duration_months
             FROM registrations r JOIN courses c ON c.id = r.course_id WHERE r.id = ?"
        );
        $st->execute([$registrationId]);
        $r = $st->fetch(PDO::FETCH_ASSOC);
        $cert = lor_certificate($db, $registrationId);
        if (!$r || !$cert) {
            return '';
        }
        $name = trim($r['full_name']);
        if ($name === mb_strtolower($name) || $name === mb_strtoupper($name)) {
            $name = mb_convert_case($name, MB_CASE_TITLE, 'UTF-8');
        }
        $first = explode(' ', $name)[0];
        $course = trim((string) ($cert['snapshot_course'] ?: $r['title']));
        $months = max(1, (int) ($cert['snapshot_duration_months'] ?: $r['duration_months']));
        $from = date('F Y', strtotime($r['created_at'] ?: 'now'));
        $to = date('F Y', strtotime($cert['issued_at'] ?? $r['studies_completed_at'] ?? 'now') ?: time());
        $topics = lor_course_topics($r);
        $overview = trim((string) $r['overview']);

        $p = [];
        $p[] = 'To Whom It May Concern,';
        $p[] = 'It is with great pleasure that Dazu Training Institute recommends ' . $name . ' (Registration No. ' . $r['registration_no'] . '), '
             . 'who successfully completed the ' . $months . '-month ' . $course . ' programme with us between ' . $from . ' and ' . $to
             . ', and was awarded certificate number ' . $cert['certificate_no'] . '.';
        if ($topics) {
            $last = array_pop($topics);
            $p[] = 'During the programme, ' . $first . ' gained practical, hands-on experience in '
                 . ($topics ? implode(', ', $topics) . ' and ' : '') . $last . '.';
        } elseif ($overview !== '') {
            $p[] = 'The programme prepares students to ' . lcfirst(rtrim($overview, '.')) . '. ' . $first . ' completed all of its practical work and assessments.';
        } else {
            $p[] = 'During the programme, ' . $first . ' completed all of the practical work and assessments required for the ' . $course . ' course.';
        }
        if (trim((string) $cert['taught_skills']) !== '') {
            $p[] = 'In the words of the course tutor: ' . rtrim(trim($cert['taught_skills']), '.') . '.';
        }
        $p[] = 'Throughout the course, ' . $first . ' showed commitment, discipline and a genuine willingness to learn, worked well with fellow students and tutors, '
             . 'and applied new skills with confidence. We are confident that ' . $first . ' will be a valuable member of any organisation or institution of further learning, '
             . 'and we recommend ' . $first . ' without reservation.';
        $p[] = 'This letter can be verified at ' . preg_replace('#^https?://#', '', rtrim(cert_verify_url(), '/')) . ' using the registration number above.';
        return implode("\n\n", $p);
    }

    /**
     * Create the letter (or return the existing one). Needs a generated certificate.
     * @return array{ok:bool, id?:int, error?:string, existed?:bool}
     */
    function lor_generate(PDO $db, int $registrationId, int $createdBy): array
    {
        $cert = lor_certificate($db, $registrationId);
        if (!$cert) {
            return ['ok' => false, 'error' => 'Generate the certificate first — the letter of recommendation is only available after it.'];
        }
        try {
            if ($existing = lor_get_by_reg($db, $registrationId)) {
                return ['ok' => true, 'id' => (int) $existing['id'], 'existed' => true];
            }
            $db->prepare('INSERT INTO recommendation_letters (registration_id, certificate_id, body, verify_hash, created_by) VALUES (?, ?, ?, ?, ?)')
               ->execute([$registrationId, (int) $cert['id'], lor_default_body($db, $registrationId), bin2hex(random_bytes(16)), $createdBy ?: null]);
        } catch (PDOException $e) {
            return ['ok' => false, 'error' => 'The recommendation letters table is not installed yet. Run System Updates (migration 072).'];
        }
        $id = (int) $db->lastInsertId();
        require_once __DIR__ . '/PortalNotifications.php';
        $uid = (int) ($db->query('SELECT user_id FROM registrations WHERE id = ' . $registrationId)->fetchColumn() ?: 0);
        if ($uid) {
            PortalNotifications::notify($db, $uid, 'certificate', 'Your letter of recommendation is ready 📄',
                'Download it from My Certificates. A copy was emailed to you.', 'students/certificates/index.php');
        }
        return ['ok' => true, 'id' => $id];
    }

    /** Admin/superadmin edit. An empty body resets it to the system text. */
    function lor_update_body(PDO $db, int $id, string $body, int $editorId): void
    {
        $body = trim(str_replace("\r\n", "\n", $body));
        if ($body === '') {
            $l = lor_get($db, $id);
            $body = $l ? lor_default_body($db, (int) $l['registration_id']) : '';
        }
        $db->prepare('UPDATE recommendation_letters SET body = ?, edited_by = ?, edited_at = NOW() WHERE id = ?')
           ->execute([mb_substr($body, 0, 6000), $editorId ?: null, $id]);
    }

    function lor_pdf_filename(array $l): string
    {
        return 'Recommendation_Letter_' . trim(preg_replace('/[^A-Za-z0-9_\-]+/', '_', (string) $l['registration_no']), '_') . '.pdf';
    }

    function lor_pdf_bytes(array $l): string
    {
        require_once __DIR__ . '/../helpers/recommendation_pdf.php';
        return lor_render_pdf($l);
    }

    /** Email the PDF to the student and stamp emailed_at. */
    function lor_send_email(PDO $db, int $id): array
    {
        require_once __DIR__ . '/StaffIdService.php';
        $l = lor_get($db, $id);
        if (!$l) {
            return ['ok' => false, 'message' => 'Letter not found.'];
        }
        $to = trim((string) $l['reg_email']) ?: trim((string) $l['login_email']);
        try {
            $res = idc_send_pdf_email($to, $l['full_name'], 'Your letter of recommendation',
                'Congratulations on completing <strong>' . htmlspecialchars((string) $l['snapshot_course']) . '</strong>. Your letter of recommendation is attached. '
                . 'You can download it again any time from <strong>My Certificates</strong> in the student portal.',
                lor_pdf_bytes($l), lor_pdf_filename($l));
        } catch (Throwable $e) {
            error_log('[lor email] ' . $e->getMessage());
            return ['ok' => false, 'message' => 'The letter PDF could not be created.'];
        }
        if (!empty($res['skipped'])) {
            return ['ok' => false, 'message' => 'Email is turned off on this site, so the letter was not emailed.'];
        }
        if ($res['ok']) {
            $db->prepare('UPDATE recommendation_letters SET emailed_at = NOW() WHERE id = ?')->execute([$id]);
            return ['ok' => true, 'message' => 'Letter emailed to ' . $to . '.'];
        }
        return ['ok' => false, 'message' => 'The letter could not be emailed: ' . ($res['message'] ?? 'unknown error') . '.'];
    }
}
